font-style: italic;
font-variant: small-caps;
line-height: 90%;
}

---

a:focus,
button:focus,
input:focus {
outline: 2px solid orange;
}

---

button:focus {
outline: none;
}

---

button:focus {
outline: 2px solid orange;
}

---

nav {
background-color: #333333;
color: white;
}
aside {
background-color: #333333;
color: white;
}

---

@media (prefers-reduced-motion: reduce) {
* {
animation: none !important;
transition: none !important;
}
}
```
